import { ecosystemApps, getAssetForApp, getAppKeyFromHost } from '../lib/ecosystem.js';
import ScreenRecorder from './ScreenRecorder.jsx';

const EcosystemNav = ({ className = '', showRecorder = true, streamApiUrl = 'https://videostream.vegvisr.org', onRecordingComplete }) => {
  const activeKey =
    typeof window === 'undefined' ? null : getAppKeyFromHost(window.location.hostname);

  return (
    <div className={`flex flex-wrap items-center gap-3 ${className}`.trim()}>
      {ecosystemApps.map((app) => {
        const iconSrc = app.icon || getAssetForApp(app.key, 'icon');
        const isActive = activeKey === app.key;
        return (
          <a
            key={app.key}
            href={app.url}
            className={`flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-semibold uppercase tracking-[0.3em] transition ${
              isActive
                ? 'border-sky-400/60 bg-sky-500/20 text-white'
                : 'border-white/20 bg-white/5 text-white/70 hover:bg-white/10'
            }`}
          >
            {iconSrc ? (
              <img
                src={iconSrc}
                alt={app.label}
                className="h-4 w-4 rounded-full object-contain"
              />
            ) : (
              <span className="flex h-4 w-4 items-center justify-center rounded-full bg-white/20 text-[10px]">
                {app.label.slice(0, 1)}
              </span>
            )}
            <span className="text-[10px]">{app.label}</span>
          </a>
        );
      })}
      {showRecorder && (
        <ScreenRecorder
          className="ml-auto"
          streamApiUrl={streamApiUrl}
          onRecordingComplete={onRecordingComplete}
        />
      )}
    </div>
  );
};

export default EcosystemNav;
